const targetId = String((($('Webhook Pagar').item.json.query) || {}).landing_id || '').trim();
if (!targetId) {
  return [{ json: { erro: 'Falta o parâmetro landing_id.' } }];
}

const items = $input.all();
let state = null;
let stateFileName = '';
for (let i = 0; i < items.length; i++) {
  if (!items[i].binary || !items[i].binary.data) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let s;
  try { s = JSON.parse(buf.toString('utf8')); } catch (e) { continue; }
  if (s.landing_id === targetId) {
    state = s;
    stateFileName = (items[i].binary.data.fileName || '').split('/').pop();
    break;
  }
}

if (!state) {
  return [{ json: { erro: 'Esta página de pré-visualização não foi encontrada (pode já ter expirado).' } }];
}
if (state.estado === 'publicado') {
  return [{ json: { erro: '', jaPublicado: true, canonical: state.url } }];
}

// PRISMA CONFIG CENTRAL -- pagamento (ver nota identica no no "Valida e Processa Callback")
const PRISMA_PAYMENT_AMOUNT = 100; // centimos -- EUR 1,00, valor de teste simbolico da Fase 2.2 (decisao do operador). O preco real so se define na Fase 3 -- mudar SO aqui e no callback.

// Reaproveita uma ordem pendente recente (<30 min) em vez de gerar uma nova a cada clique/reload
const agora = Date.now();
const pendenteRecente = !!state.payment_order_id && state.payment_status === 'pendente' &&
  !!state.payment_order_criado_em && (agora - new Date(state.payment_order_criado_em).getTime()) < 30 * 60 * 1000;

const orderId = pendenteRecente ? state.payment_order_id : String(agora);
if (!pendenteRecente) {
  state.payment_order_id = orderId;
  state.payment_status = 'pendente';
  state.payment_order_criado_em = new Date().toISOString();
}

const titulo = state.imovel?.titulo || 'Imóvel Prisma';
const out = Buffer.from(JSON.stringify(state, null, 2), 'utf8');
return [{
  json: { erro: '', jaPublicado: false, orderId, stateFileName, titulo, amountEuros: (PRISMA_PAYMENT_AMOUNT / 100).toFixed(2) },
  binary: { state: await this.helpers.prepareBinaryData(out, stateFileName, 'application/json') }
}];

// TODO -- confirmar os nomes exatos dos campos de resposta assim que a conta
// ifthenpay existir e a chamada real puder ser testada (P1/P2, credenciais
// em placeholder ate la). Hoje a chave do gateway e um placeholder, por isso
// esta chamada falha sempre de forma controlada -- o utilizador ve a pagina
// "pagamento indisponivel", nunca um erro cru.
const resp = $json;
const erroGateway = resp.error ? String((resp.error && resp.error.message) || resp.error) : '';
const redirectUrl = !erroGateway
  ? (resp.PaymentUrl || resp.paymentUrl || resp.redirectUrl || resp.RedirectUrl || resp.url || resp.Url || '')
  : '';
return [{ json: { redirectUrl, gatewayOk: !!redirectUrl } }];

const q = $json.query || {};
return [{ json: {
  key: q.key || '',
  id: q.id || '',
  amount: q.amount || '',
  payment_datetime: q.payment_datetime || '',
  payment_method: q.payment_method || ''
} }];

const b = $json.body || {};
const q = $json.query || {};
return [{ json: {
  key: (b.key ?? q.key) || '',
  id: (b.id ?? q.id) || '',
  amount: (b.amount ?? q.amount) || '',
  payment_datetime: (b.payment_datetime ?? q.payment_datetime) || '',
  payment_method: (b.payment_method ?? q.payment_method) || ''
} }];

// PRISMA CONFIG CENTRAL -- pagamento (replicado, ver nota identica no no
// "Resolve Landing Pagamento" e em imovel-landing-wf.json/imovel-cron-expiracao-wf.json
// para os links do botao "Publicar o meu site"/"Reativar a minha pagina").
const PRISMA_PAYMENT_AMOUNT = 100; // centimos -- EUR 1,00, valor de teste simbolico da Fase 2.2. Mudar SO aqui e no "Resolve Landing Pagamento" quando o preco real for definido (Fase 3).
// TODO SUBSTITUIR -- chave anti-phishing real, gerada no backoffice do gateway
// escolhido (ver relatorio P1) depois de o operador abrir conta. Sem esta troca
// qualquer POST/GET a este endpoint e rejeitado (chaveValida fica sempre falsa),
// o que e seguro por omissao mas nao publica nada ate ser configurada.
const PRISMA_PAYMENT_CALLBACK_SECRET = 'SUBSTITUIR_CHAVE_ANTIPHISHING_GATEWAY';
const PRISMA_OPERATOR_EMAIL = 'ibissonsilva@gmail.com';

let cb = null;
try { cb = $('Normaliza Callback GET').item.json; } catch (e) { /* esta execucao veio do POST */ }
if (!cb) { try { cb = $('Normaliza Callback POST').item.json; } catch (e) { /* nem GET nem POST -- nao devia acontecer */ } }
if (!cb) throw new Error('PAGAMENTO CONFIRMADO: sem dados de callback (nem GET nem POST executaram nesta run).');

const chaveValida = !!cb.key && cb.key === PRISMA_PAYMENT_CALLBACK_SECRET;
const orderId = String(cb.id || '').trim();

const items = $input.all();
let stateFound = null;
let stateFileName = '';
for (let i = 0; i < items.length; i++) {
  if (!items[i].binary || !items[i].binary.data) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let s;
  try { s = JSON.parse(buf.toString('utf8')); } catch (e) { continue; }
  if (orderId && String(s.payment_order_id || '') === orderId) {
    stateFound = s;
    stateFileName = (items[i].binary.data.fileName || '').split('/').pop();
    break;
  }
}

// P3 -- callback repetido, chave invalida ou landing desconhecida: NUNCA processa
// de novo (nem republica, nem reenvia email) -- so confirma 200 ao gateway (ou,
// no caso de chave invalida, simplesmente nao ha nada de sensivel para expor).
// jaConfirmado tambem cai aqui -- e o proprio mecanismo de idempotencia do P3.
const jaConfirmado = !!(stateFound && stateFound.payment_confirmado === true);
if (!chaveValida || !stateFound || jaConfirmado) {
  return [{ json: {
    precisaProcessar: false,
    motivo: !chaveValida ? 'chave_invalida' : (!stateFound ? 'landing_nao_encontrada' : 'ja_processado'),
    orderId
  } }];
}

// P3 -- valor tem de bater certo com o esperado; formatos de "amount" variam por
// gateway (ex.: "1.00"), por isso normaliza sempre para centimos antes de comparar.
const amountRecebidoCentimos = Math.round(parseFloat(String(cb.amount || '0').replace(',', '.')) * 100) || 0;
const valorCorreto = amountRecebidoCentimos === PRISMA_PAYMENT_AMOUNT;

stateFound.payment_status = valorCorreto ? 'confirmado' : 'valor_incorreto';
stateFound.payment_confirmado = valorCorreto;
stateFound.payment_confirmado_em = new Date().toISOString();
stateFound.payment_gateway_amount = cb.amount || null;
stateFound.payment_method = cb.payment_method || null;

const titulo = stateFound.imovel?.titulo || 'O seu imóvel';
const targetEmail = String(stateFound.cliente?.corretor?.email || '').trim() || PRISMA_OPERATOR_EMAIL;

const out = Buffer.from(JSON.stringify(stateFound, null, 2), 'utf8');
return [{
  json: {
    precisaProcessar: true,
    valorCorreto,
    orderId,
    stateFileName,
    canonical: stateFound.url,
    titulo,
    targetEmail,
    valorEsperadoEuros: (PRISMA_PAYMENT_AMOUNT / 100).toFixed(2),
    valorRecebido: cb.amount || '',
    operatorEmail: PRISMA_OPERATOR_EMAIL
  },
  binary: { state: await this.helpers.prepareBinaryData(out, stateFileName, 'application/json') }
}];

// ===== PRISMA CONFIG CENTRAL (N5, replicado -- ver nota em imovel-landing-wf.json) =====
const PRISMA_BRAND_NAME = 'Prisma';

function escapeHtml(unsafe) {
  if (unsafe === undefined || unsafe === null) return '';
  return String(unsafe).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}
function escapeAttr(unsafe) {
  if (unsafe === undefined || unsafe === null) return '';
  return String(unsafe).replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

// N4 -- template de email (replicado, ver nota em imovel-landing-wf.json).
function buildEmailPrisma({ brandName, preheader, headline, bodyHtml, ctaLabel, ctaUrl }) {
  const brand = escapeHtml(brandName || PRISMA_BRAND_NAME);
  const fontStack = `-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif`;
  const ctaBlock = ctaUrl ? `
    <table role="presentation" cellpadding="0" cellspacing="0" style="margin-top:24px;">
      <tr><td style="border-radius:6px;background-color:#8c6d4f;">
        <a href="${escapeAttr(ctaUrl)}" style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;font-family:${fontStack};">${escapeHtml(ctaLabel || '')}</a>
      </td></tr>
    </table>` : '';
  return `<!DOCTYPE html>
<html lang="pt">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${brand}</title>
</head>
<body style="margin:0;padding:0;background-color:#f4f2ef;font-family:${fontStack};">
<span style="display:none;font-size:1px;color:#f4f2ef;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;">${escapeHtml(preheader || '')}</span>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f2ef;padding:32px 16px;"><tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background-color:#ffffff;border-radius:8px;overflow:hidden;">
<tr><td style="background-color:#1c2421;padding:24px 32px;"><span style="font-size:20px;font-weight:600;color:#ffffff;letter-spacing:0.02em;font-family:${fontStack};">${brand}</span></td></tr>
<tr><td style="padding:32px 32px 8px;">
<h1 style="margin:0 0 16px;font-size:22px;line-height:1.3;color:#1c2421;font-family:${fontStack};">${escapeHtml(headline || '')}</h1>
<div style="font-size:15px;line-height:1.6;color:#3f3f3f;font-family:${fontStack};">${bodyHtml}</div>
${ctaBlock}
</td></tr>
<tr><td style="padding:20px 32px 28px;background-color:#f1ede6;border-top:1px solid #e5e0d8;">
<p style="margin:0;font-size:12px;color:#8a8a8a;line-height:1.5;font-family:${fontStack};">Esta é uma mensagem automática do ${brand}. Pode responder a este email diretamente com alterações ou dúvidas.</p>
</td></tr>
</table>
</td></tr></table>
</body>
</html>`;
}

const rj = $('Valida e Processa Callback').item.json;
const titulo = rj.titulo;
const canonical = rj.canonical;
const targetEmail = rj.targetEmail;

const bodyHtml = `
<p>Boas notícias: o pagamento foi confirmado e a página do imóvel <strong>${escapeHtml(titulo)}</strong> está publicada, já sem data de expiração.</p>
<p style="margin:20px 0;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="border-radius:6px;background-color:#8c6d4f;"><a href="${escapeAttr(canonical)}" style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#ffffff;text-decoration:none;">Ver a minha página</a></td></tr></table></p>
<p style="margin:8px 0 0;font-size:12px;color:#8a8a8a;word-break:break-all;">${escapeHtml(canonical)}</p>
<p style="margin-top:24px;">Encontrou algo para corrigir? Basta responder a este email a descrever a alteração.</p>
`;

const html = buildEmailPrisma({
  brandName: PRISMA_BRAND_NAME,
  preheader: 'Pagamento confirmado -- a sua página está publicada.',
  headline: 'A sua página está publicada',
  bodyHtml,
  ctaLabel: '',
  ctaUrl: ''
});

const subject = 'Pagamento confirmado — ' + titulo + ' está publicado';

return [{ json: { targetEmail, subject, html } }];

